import threading
import psycopg.errors

def reproduce(connect, service) -> str | None:
    N_THREADS = 8
    ITERS = 20
    barrier = threading.Barrier(N_THREADS)
    found = []
    lock = threading.Lock()

    def worker(idx):
        from_id = 1 if (idx % 2 == 0) else 2
        to_id = 2 if (idx % 2 == 0) else 1
        try:
            with connect() as conn:
                for _ in range(ITERS):
                    try:
                        barrier.wait(timeout=15)
                    except threading.BrokenBarrierError:
                        return
                    try:
                        service.transfer(conn, from_id, to_id, 1)
                    except psycopg.errors.DeadlockDetected:
                        with lock:
                            found.append(1)
                    except Exception as e:
                        msg = (str(e) + " " + type(e).__name__).lower()
                        if "deadlock" in msg:
                            with lock:
                                found.append(1)
                        # ignore other expected errors like InsufficientFunds for this repro
                        pass
        except Exception:
            pass

    threads = [threading.Thread(target=worker, args=(i,)) for i in range(N_THREADS)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=60)

    if found:
        return f"deadlock detected: {len(found)} opposite-direction transfers failed with deadlock (money movement liveness broken)"
    return None

