"""Money transfer service."""
import psycopg


class InsufficientFunds(Exception):
    pass


def transfer(conn: psycopg.Connection, from_id: int, to_id: int, amount: int) -> None:
    with conn.transaction():
        if from_id == to_id:
            row = conn.execute(
                "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (from_id,)
            ).fetchone()
            if row is None:
                raise ValueError("unknown account")
            if row[0] < amount:
                raise InsufficientFunds(from_id)
            conn.execute("UPDATE accounts SET balance = balance - %s WHERE id = %s", (amount, from_id))
            conn.execute("UPDATE accounts SET balance = balance + %s WHERE id = %s", (amount, to_id))
            return
        # Lock rows in a consistent global order (sorted by id) to avoid deadlocks
        # between concurrent opposite-direction transfers.
        first_id, second_id = (from_id, to_id) if from_id < to_id else (to_id, from_id)
        first = conn.execute(
            "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (first_id,)
        ).fetchone()
        second = conn.execute(
            "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (second_id,)
        ).fetchone()

        if first is None or second is None:
            raise ValueError("unknown account")
        if from_id < to_id:
            sender = first
            receiver = second
        else:
            sender = second
            receiver = first
        if sender[0] < amount:
            raise InsufficientFunds(from_id)

        conn.execute("UPDATE accounts SET balance = balance - %s WHERE id = %s", (amount, from_id))
        conn.execute("UPDATE accounts SET balance = balance + %s WHERE id = %s", (amount, to_id))
